    pub(crate) async fn schedule_write_op(
        inner: &Arc<Inner<K, V, S>>,
        ch: &Sender<WriteOp<K, V>>,
        ch_ready_event: &event_listener::Event<()>,
        op: WriteOp<K, V>,
